-- Lion Vs Tiger alone has no business stake cap. Legacy limits remain exact.
-- Add nullable game discriminators: old binaries keep inserting NULL safely.
-- The composite FK prevents claiming a legacy round is Lion Vs Tiger.
SET @lt_sql := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='game_shared_bet_requests' AND COLUMN_NAME='game_name')=0, 'ALTER TABLE game_shared_bet_requests ADD COLUMN game_name VARCHAR(64) NULL', 'SELECT 1');
PREPARE lt_statement FROM @lt_sql;
EXECUTE lt_statement;
DEALLOCATE PREPARE lt_statement;
SET @lt_sql := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='game_shared_bets' AND COLUMN_NAME='game_name')=0, 'ALTER TABLE game_shared_bets ADD COLUMN game_name VARCHAR(64) NULL', 'SELECT 1');
PREPARE lt_statement FROM @lt_sql;
EXECUTE lt_statement;
DEALLOCATE PREPARE lt_statement;
SET @lt_sql := IF((SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='game_shared_rounds' AND INDEX_NAME='uq_shared_round_id_game')=0, 'ALTER TABLE game_shared_rounds ADD UNIQUE INDEX uq_shared_round_id_game (id,game_name)', 'SELECT 1');
PREPARE lt_statement FROM @lt_sql;
EXECUTE lt_statement;
DEALLOCATE PREPARE lt_statement;
SET @lt_sql := IF((SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='game_shared_bet_requests' AND CONSTRAINT_NAME='fk_shared_request_game')=0, 'ALTER TABLE game_shared_bet_requests ADD CONSTRAINT fk_shared_request_game FOREIGN KEY (round_id,game_name) REFERENCES game_shared_rounds(id,game_name)', 'SELECT 1');
PREPARE lt_statement FROM @lt_sql;
EXECUTE lt_statement;
DEALLOCATE PREPARE lt_statement;
SET @lt_sql := IF((SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='game_shared_bets' AND CONSTRAINT_NAME='fk_shared_bet_game')=0, 'ALTER TABLE game_shared_bets ADD CONSTRAINT fk_shared_bet_game FOREIGN KEY (round_id,game_name) REFERENCES game_shared_rounds(id,game_name)', 'SELECT 1');
PREPARE lt_statement FROM @lt_sql;
EXECUTE lt_statement;
DEALLOCATE PREPARE lt_statement;
SET @lt_drop := (SELECT GROUP_CONCAT(DISTINCT CONCAT(IF(VERSION() LIKE '%MariaDB%', 'DROP CONSTRAINT `', 'DROP CHECK `'),t.CONSTRAINT_NAME,'`') SEPARATOR ', ') FROM information_schema.TABLE_CONSTRAINTS t INNER JOIN information_schema.CHECK_CONSTRAINTS c ON c.CONSTRAINT_SCHEMA=t.CONSTRAINT_SCHEMA AND c.CONSTRAINT_NAME=t.CONSTRAINT_NAME WHERE t.CONSTRAINT_SCHEMA=DATABASE() AND t.TABLE_NAME='game_shared_bet_requests' AND t.CONSTRAINT_TYPE='CHECK' AND t.CONSTRAINT_NAME<>'chk_shared_request_game_amount' AND c.CHECK_CLAUSE LIKE '%wager_total%' AND c.CHECK_CLAUSE LIKE '%50000000%');
SET @lt_sql := IF(@lt_drop IS NULL, 'SELECT 1', CONCAT('ALTER TABLE game_shared_bet_requests ',@lt_drop));
PREPARE lt_statement FROM @lt_sql;
EXECUTE lt_statement;
DEALLOCATE PREPARE lt_statement;
SET @lt_sql := IF((SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='game_shared_bet_requests' AND CONSTRAINT_NAME='chk_shared_request_game_amount')=0, 'ALTER TABLE game_shared_bet_requests ADD CONSTRAINT chk_shared_request_game_amount CHECK (wager_total > 0 AND ((wager_total <= 50000000) OR (COALESCE(game_name,'''') = ''lion_vs_tiger'' AND wager_total <= 9007199254740991)))', 'SELECT 1');
PREPARE lt_statement FROM @lt_sql;
EXECUTE lt_statement;
DEALLOCATE PREPARE lt_statement;
SET @lt_drop := (SELECT GROUP_CONCAT(DISTINCT CONCAT(IF(VERSION() LIKE '%MariaDB%', 'DROP CONSTRAINT `', 'DROP CHECK `'),t.CONSTRAINT_NAME,'`') SEPARATOR ', ') FROM information_schema.TABLE_CONSTRAINTS t INNER JOIN information_schema.CHECK_CONSTRAINTS c ON c.CONSTRAINT_SCHEMA=t.CONSTRAINT_SCHEMA AND c.CONSTRAINT_NAME=t.CONSTRAINT_NAME WHERE t.CONSTRAINT_SCHEMA=DATABASE() AND t.TABLE_NAME='game_shared_bets' AND t.CONSTRAINT_TYPE='CHECK' AND t.CONSTRAINT_NAME<>'chk_shared_bet_game_amount' AND c.CHECK_CLAUSE LIKE '%amount%' AND c.CHECK_CLAUSE LIKE '%50000000%');
SET @lt_sql := IF(@lt_drop IS NULL, 'SELECT 1', CONCAT('ALTER TABLE game_shared_bets ',@lt_drop));
PREPARE lt_statement FROM @lt_sql;
EXECUTE lt_statement;
DEALLOCATE PREPARE lt_statement;
SET @lt_sql := IF((SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='game_shared_bets' AND CONSTRAINT_NAME='chk_shared_bet_game_amount')=0, 'ALTER TABLE game_shared_bets ADD CONSTRAINT chk_shared_bet_game_amount CHECK (amount > 0 AND ((amount <= 50000000) OR (COALESCE(game_name,'''') = ''lion_vs_tiger'' AND amount <= 9007199254740991)))', 'SELECT 1');
PREPARE lt_statement FROM @lt_sql;
EXECUTE lt_statement;
DEALLOCATE PREPARE lt_statement;
SET @lt_drop := (SELECT GROUP_CONCAT(DISTINCT CONCAT(IF(VERSION() LIKE '%MariaDB%', 'DROP CONSTRAINT `', 'DROP CHECK `'),t.CONSTRAINT_NAME,'`') SEPARATOR ', ') FROM information_schema.TABLE_CONSTRAINTS t INNER JOIN information_schema.CHECK_CONSTRAINTS c ON c.CONSTRAINT_SCHEMA=t.CONSTRAINT_SCHEMA AND c.CONSTRAINT_NAME=t.CONSTRAINT_NAME WHERE t.CONSTRAINT_SCHEMA=DATABASE() AND t.TABLE_NAME='game_round_results' AND t.CONSTRAINT_TYPE='CHECK' AND t.CONSTRAINT_NAME<>'chk_result_game_wager' AND c.CHECK_CLAUSE LIKE '%wager_total%' AND c.CHECK_CLAUSE LIKE '%50000000%');
SET @lt_sql := IF(@lt_drop IS NULL, 'SELECT 1', CONCAT('ALTER TABLE game_round_results ',@lt_drop));
PREPARE lt_statement FROM @lt_sql;
EXECUTE lt_statement;
DEALLOCATE PREPARE lt_statement;
SET @lt_sql := IF((SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='game_round_results' AND CONSTRAINT_NAME='chk_result_game_wager')=0, 'ALTER TABLE game_round_results ADD CONSTRAINT chk_result_game_wager CHECK (wager_total >= 0 AND ((wager_total <= 50000000) OR (COALESCE(game_name,'''') = ''lion_vs_tiger'' AND wager_total <= 9007199254740991)))', 'SELECT 1');
PREPARE lt_statement FROM @lt_sql;
EXECUTE lt_statement;
DEALLOCATE PREPARE lt_statement;
SET @lt_drop := (SELECT GROUP_CONCAT(DISTINCT CONCAT(IF(VERSION() LIKE '%MariaDB%', 'DROP CONSTRAINT `', 'DROP CHECK `'),t.CONSTRAINT_NAME,'`') SEPARATOR ', ') FROM information_schema.TABLE_CONSTRAINTS t INNER JOIN information_schema.CHECK_CONSTRAINTS c ON c.CONSTRAINT_SCHEMA=t.CONSTRAINT_SCHEMA AND c.CONSTRAINT_NAME=t.CONSTRAINT_NAME WHERE t.CONSTRAINT_SCHEMA=DATABASE() AND t.TABLE_NAME='game_round_results' AND t.CONSTRAINT_TYPE='CHECK' AND t.CONSTRAINT_NAME<>'chk_result_game_payout' AND c.CHECK_CLAUSE LIKE '%payout_total%' AND c.CHECK_CLAUSE LIKE '%1250000000%');
SET @lt_sql := IF(@lt_drop IS NULL, 'SELECT 1', CONCAT('ALTER TABLE game_round_results ',@lt_drop));
PREPARE lt_statement FROM @lt_sql;
EXECUTE lt_statement;
DEALLOCATE PREPARE lt_statement;
SET @lt_sql := IF((SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA=DATABASE() AND TABLE_NAME='game_round_results' AND CONSTRAINT_NAME='chk_result_game_payout')=0, 'ALTER TABLE game_round_results ADD CONSTRAINT chk_result_game_payout CHECK (payout_total >= 0 AND ((payout_total <= 1250000000) OR (COALESCE(game_name,'''') = ''lion_vs_tiger'' AND payout_total <= 9007199254740991)))', 'SELECT 1');
PREPARE lt_statement FROM @lt_sql;
EXECUTE lt_statement;
DEALLOCATE PREPARE lt_statement;
